-- Staging-only migration 213: persistent, supervised and reversible email routing learning.
begin;
set local lock_timeout='10s';
set local statement_timeout='180s';
select pg_advisory_xact_lock(hashtextextended('pdc-staging-migration-213-persistent-supervised-learning',0));
select public.pdc_monitor_staging_guard();
do $guard$
begin
 if not public.pdc_monitor_staging_guard()
    or not exists(select 1 from public.pdc_staging_environment_sentinel where singleton and project_ref='cdsmnqxtyyoeoznmbidd')
    or to_regclass('public.pdc_production_environment_sentinel') is not null
    or not exists(select 1 from supabase_migrations.schema_migrations where version='212' and name='retained_uid_1477_recreation_import')
    or exists(select 1 from supabase_migrations.schema_migrations where version ~ '^[0-9]+$' and version::integer>212)
    or exists(select 1 from supabase_migrations.schema_migrations where version='213')
    or to_regclass('public.pdc_authenticated_email_operation_lines') is null
    or to_regclass('public.vehicle_workshop_line_adjustments') is null then
  raise exception 'PDC_213_STAGING_OR_LEDGER_MISMATCH' using errcode='55000';
 end if;
end $guard$;

create table public.pdc_supervised_rule_families(
 family_id uuid primary key default gen_random_uuid(), family_key text not null unique check(family_key~'^[a-z][a-z0-9_]{2,79}$'),
 title text not null check(length(btrim(title)) between 3 and 160), created_by uuid not null references auth.users(id) on delete restrict,
 created_by_email text not null, created_at timestamptz not null default clock_timestamp()
);
create table public.pdc_supervised_rule_versions(
 version_id uuid primary key default gen_random_uuid(), family_id uuid not null references public.pdc_supervised_rule_families(family_id) on delete restrict,
 version_no integer not null check(version_no>0), predecessor_version_id uuid references public.pdc_supervised_rule_versions(version_id) on delete restrict,
 original_telegram_instruction text not null check(length(btrim(original_telegram_instruction)) between 3 and 4000), authorized_by uuid not null references auth.users(id) on delete restrict,
 authorized_by_email text not null, proposed_by uuid not null references auth.users(id) on delete restrict,
 effective_from timestamptz not null, effective_until timestamptz, priority integer not null check(priority between 0 and 100000),
 confidence numeric(5,4) not null check(confidence between 0 and 1), match_kind text not null check(match_kind in('operation_code','exact_description','phrase','existing_mapping','inference_review')),
 operation_code text, normalized_description text, phrase_category text, work_key text not null check(work_key in('bus4x4','tint','hoist','fitting','fabrication','electrical','tyre','pitInspection','PARTS','sublet')),
 estimated_hours numeric(8,2), cost_ex_gst numeric(12,2), sell_ex_gst numeric(12,2), gst_percent numeric(5,2), currency text,
 created_at timestamptz not null default clock_timestamp(),
 unique(family_id,version_no), unique(version_id,family_id),
 check(effective_until is null or effective_until>effective_from),
 check(operation_code is null or operation_code~'^[A-Z0-9][A-Z0-9._/-]{0,39}$'),
 check(normalized_description is null or (normalized_description=lower(btrim(normalized_description)) and length(normalized_description) between 2 and 240)),
 check(phrase_category is null or phrase_category~'^[a-z][a-z0-9_]{1,79}$'),
 check((match_kind='operation_code' and operation_code is not null) or (match_kind='exact_description' and normalized_description is not null) or (match_kind='phrase' and phrase_category is not null) or match_kind in('existing_mapping','inference_review')),
 check((estimated_hours is null or estimated_hours between 0 and 999.99) and (cost_ex_gst is null or cost_ex_gst>=0) and (sell_ex_gst is null or sell_ex_gst>=0)),
 check((cost_ex_gst is null and sell_ex_gst is null and gst_percent is null and currency is null) or (cost_ex_gst is not null and sell_ex_gst is not null and gst_percent in(0,10) and currency='AUD'))
);
create table public.pdc_supervised_rule_aliases(alias_id uuid primary key default gen_random_uuid(),version_id uuid not null references public.pdc_supervised_rule_versions(version_id) on delete restrict,alias text not null check(alias=lower(btrim(alias)) and length(alias) between 2 and 240),created_at timestamptz not null default clock_timestamp(),unique(version_id,alias));
create table public.pdc_supervised_rule_examples(example_id uuid primary key default gen_random_uuid(),version_id uuid not null references public.pdc_supervised_rule_versions(version_id) on delete restrict,example_kind text not null check(example_kind in('positive','negative','deleted_evidence','correction_evidence')),example_text text not null check(length(btrim(example_text)) between 2 and 1000),source_stock text,source_operation_line_id uuid,created_at timestamptz not null default clock_timestamp());
create table public.pdc_supervised_rule_events(event_id uuid primary key default gen_random_uuid(),family_id uuid not null references public.pdc_supervised_rule_families(family_id) on delete restrict,version_id uuid references public.pdc_supervised_rule_versions(version_id) on delete restrict,event_kind text not null check(event_kind in('proposed','activated','superseded','disabled','undo')),reason text not null check(length(btrim(reason)) between 3 and 1000),actor_id uuid not null references auth.users(id) on delete restrict,actor_email text not null,created_at timestamptz not null default clock_timestamp());
create table public.pdc_supervised_correction_batches(batch_id uuid primary key default gen_random_uuid(),idempotency_key text not null unique check(length(idempotency_key) between 12 and 160),request_hash text not null check(request_hash~'^[a-f0-9]{64}$'),reason text not null,created_by uuid not null references auth.users(id) on delete restrict,created_by_email text not null,created_at timestamptz not null default clock_timestamp());
create table public.pdc_supervised_correction_items(item_id uuid primary key default gen_random_uuid(),batch_id uuid not null references public.pdc_supervised_correction_batches(batch_id) on delete restrict,operation_line_id uuid not null references public.pdc_authenticated_email_operation_lines(operation_line_id) on delete restrict,expected_stock text not null,expected_normalized_description text not null,target_work_key text not null,target_stage_code text not null,source_stage_code text not null,rule_version_id uuid references public.pdc_supervised_rule_versions(version_id) on delete restrict,created_at timestamptz not null default clock_timestamp(),unique(batch_id,operation_line_id));
create table public.pdc_supervised_correction_overlays(overlay_id uuid primary key default gen_random_uuid(),item_id uuid not null references public.pdc_supervised_correction_items(item_id) on delete restrict,operation_line_id uuid not null references public.pdc_authenticated_email_operation_lines(operation_line_id) on delete restrict,overlay_kind text not null check(overlay_kind in('apply','undo')),stage_code text not null,predecessor_overlay_id uuid references public.pdc_supervised_correction_overlays(overlay_id) on delete restrict,actor_id uuid not null references auth.users(id) on delete restrict,actor_email text not null,created_at timestamptz not null default clock_timestamp());
create table public.pdc_supervised_apply_receipts(receipt_id uuid primary key default gen_random_uuid(),batch_id uuid not null references public.pdc_supervised_correction_batches(batch_id) on delete restrict,operation_line_id uuid not null references public.pdc_authenticated_email_operation_lines(operation_line_id) on delete restrict,overlay_id uuid references public.pdc_supervised_correction_overlays(overlay_id) on delete restrict,outcome text not null check(outcome in('applied','already_effective','protected','stale','not_found','failed','undone')),detail text not null,before_effective jsonb,after_effective jsonb,actor_id uuid not null references auth.users(id) on delete restrict,actor_email text not null,created_at timestamptz not null default clock_timestamp());
create table public.pdc_supervised_failures(failure_id uuid primary key default gen_random_uuid(),rpc_name text not null,error_code text not null,error_detail text not null,actor_id uuid,actor_email text,request_context jsonb not null default '{}'::jsonb,created_at timestamptz not null default clock_timestamp());
create table public.pdc_supervised_telegram_identities(identity_id uuid primary key default gen_random_uuid(),telegram_sender_id bigint not null unique,auth_user_id uuid not null references auth.users(id) on delete restrict,actor_email text not null,authorized_by uuid not null references auth.users(id) on delete restrict,active boolean not null default true,created_at timestamptz not null default clock_timestamp());
create table public.pdc_supervised_telegram_commands(command_id uuid primary key default gen_random_uuid(),action text not null,original_instruction text not null,telegram_sender_id bigint not null,telegram_chat_id bigint not null,telegram_message_id bigint not null,actor_id uuid not null references auth.users(id) on delete restrict,actor_email text not null,request jsonb not null,result_code text not null,created_at timestamptz not null default clock_timestamp(),unique(telegram_chat_id,telegram_message_id));
create table public.pdc_supervised_monitor_applications(application_id uuid primary key default gen_random_uuid(),rule_version_id uuid not null references public.pdc_supervised_rule_versions(version_id) on delete restrict,operation_code text,source_description text not null,display_description text not null,source_work_key text,applied_work_key text not null,scope jsonb not null,resolution jsonb not null,actor_id uuid not null references auth.users(id) on delete restrict,actor_email text not null,created_at timestamptz not null default clock_timestamp());
create table public.pdc_supervised_revision(singleton boolean primary key default true check(singleton),revision bigint not null default 0,updated_at timestamptz not null default clock_timestamp());
insert into public.pdc_supervised_revision(singleton) values(true);

create function public.pdc_supervised_immutable_213() returns trigger language plpgsql security definer set search_path=pg_catalog,public as $$begin raise exception 'PDC_213_APPEND_ONLY' using errcode='55000';end$$;
do $secure$ declare t text;begin
 foreach t in array array['pdc_supervised_rule_families','pdc_supervised_rule_versions','pdc_supervised_rule_aliases','pdc_supervised_rule_examples','pdc_supervised_rule_events','pdc_supervised_correction_batches','pdc_supervised_correction_items','pdc_supervised_correction_overlays','pdc_supervised_apply_receipts','pdc_supervised_failures','pdc_supervised_telegram_identities','pdc_supervised_telegram_commands','pdc_supervised_monitor_applications'] loop
  execute format('alter table public.%I enable row level security',t);execute format('revoke all on table public.%I from public,anon,authenticated,service_role',t);execute format('create trigger %I before update or delete on public.%I for each row execute function public.pdc_supervised_immutable_213()',t||'_immutable',t);
 end loop;
 alter table public.pdc_supervised_revision enable row level security;revoke all on table public.pdc_supervised_revision from public,anon,authenticated,service_role;
end $secure$;

create function public.pdc_supervised_bump_revision_213() returns trigger language plpgsql security definer set search_path=pg_catalog,public as $$begin update public.pdc_supervised_revision set revision=revision+1,updated_at=clock_timestamp() where singleton;return null;end$$;
do $revision$ declare t text;begin foreach t in array array['pdc_supervised_rule_events','pdc_supervised_correction_overlays','pdc_supervised_apply_receipts'] loop execute format('create trigger %I after insert on public.%I for each statement execute function public.pdc_supervised_bump_revision_213()',t||'_revision',t);end loop;end $revision$;

create function public.pdc_supervised_admin_scope_213() returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,auth as $$
declare a uuid:=auth.uid();e text:=lower(btrim(coalesce(auth.jwt()->>'email','')));begin
 if not public.pdc_monitor_staging_guard() or a is null or e='' or not exists(select 1 from public.pdc_user_roles r where r.auth_user_id=a and lower(r.email)=e and r.role='administrator' and r.active and r.account_status='approved') then return public.navision_backend_response(false,'administrator_required');end if;
 return public.navision_backend_response(true,'administrator',jsonb_build_object('actor_id',a,'actor_email',e,'craig',e='craig.watson@broometoyota.com.au'));
end$$;
create function public.pdc_supervised_monitor_scope_213() returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,auth as $$
declare a uuid:=auth.uid();e text:=lower(btrim(coalesce(auth.jwt()->>'email','')));begin
 if not public.pdc_monitor_staging_guard() or a is null or e='' or not exists(select 1 from public.pdc_user_roles r join public.pdc_monitor_stage_activation_writers w on w.user_id=r.auth_user_id where r.auth_user_id=a and lower(r.email)=e and r.role in('viewer','importer') and r.active and r.account_status='approved' and w.active and w.revoked_at is null) then return public.navision_backend_response(false,'monitor_scope_required');end if;
 return public.navision_backend_response(true,'monitor_scope',jsonb_build_object('actor_id',a,'actor_email',e));
end$$;

create function public.create_pdc_supervised_rule_family_213(p_family_key text,p_title text,p_original_telegram_instruction text,p_match_kind text,p_operation_code text,p_normalized_description text,p_phrase_category text,p_work_key text,p_priority integer,p_confidence numeric,p_effective_from timestamptz,p_estimated_hours numeric default null,p_cost_ex_gst numeric default null,p_sell_ex_gst numeric default null,p_gst_percent numeric default null,p_currency text default null)
returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$declare s jsonb:=public.pdc_supervised_admin_scope_213();a uuid;e text;f uuid;v uuid;begin if not coalesce((s->>'ok')::boolean,false) then return s;end if;a=(s->'data'->>'actor_id')::uuid;e=s->'data'->>'actor_email';insert into public.pdc_supervised_rule_families(family_key,title,created_by,created_by_email) values(lower(btrim(p_family_key)),btrim(p_title),a,e) returning family_id into f;insert into public.pdc_supervised_rule_versions(family_id,version_no,original_telegram_instruction,authorized_by,authorized_by_email,proposed_by,effective_from,priority,confidence,match_kind,operation_code,normalized_description,phrase_category,work_key,estimated_hours,cost_ex_gst,sell_ex_gst,gst_percent,currency) values(f,1,btrim(p_original_telegram_instruction),a,e,a,p_effective_from,p_priority,p_confidence,p_match_kind,nullif(upper(btrim(p_operation_code)),''),nullif(lower(btrim(p_normalized_description)),''),nullif(lower(btrim(p_phrase_category)),''),p_work_key,p_estimated_hours,p_cost_ex_gst,p_sell_ex_gst,p_gst_percent,upper(p_currency)) returning version_id into v;insert into public.pdc_supervised_rule_events(family_id,version_id,event_kind,reason,actor_id,actor_email) values(f,v,'proposed','created by authorised administrator',a,e);return public.navision_backend_response(true,'rule_proposed',jsonb_build_object('family_id',f,'version_id',v));exception when others then insert into public.pdc_supervised_failures(rpc_name,error_code,error_detail,actor_id,actor_email) values('create_pdc_supervised_rule_family_213',sqlstate,sqlerrm,a,e);return public.navision_backend_response(false,'rule_create_failed');end$$;

create function public.propose_pdc_supervised_rule_version_213(p_family_id uuid,p_predecessor_version_id uuid,p_original_telegram_instruction text,p_match_kind text,p_operation_code text,p_normalized_description text,p_phrase_category text,p_work_key text,p_priority integer,p_confidence numeric,p_effective_from timestamptz,p_estimated_hours numeric default null,p_cost_ex_gst numeric default null,p_sell_ex_gst numeric default null,p_gst_percent numeric default null,p_currency text default null)
returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$declare s jsonb:=public.pdc_supervised_admin_scope_213();a uuid;e text;n int;v uuid;begin if not coalesce((s->>'ok')::boolean,false) then return s;end if;a=(s->'data'->>'actor_id')::uuid;e=s->'data'->>'actor_email';perform pg_advisory_xact_lock(hashtextextended('pdc-rule-family:'||p_family_id,0));select coalesce(max(version_no),0)+1 into n from public.pdc_supervised_rule_versions where family_id=p_family_id;insert into public.pdc_supervised_rule_versions(family_id,version_no,predecessor_version_id,original_telegram_instruction,authorized_by,authorized_by_email,proposed_by,effective_from,priority,confidence,match_kind,operation_code,normalized_description,phrase_category,work_key,estimated_hours,cost_ex_gst,sell_ex_gst,gst_percent,currency) values(p_family_id,n,p_predecessor_version_id,btrim(p_original_telegram_instruction),a,e,a,p_effective_from,p_priority,p_confidence,p_match_kind,nullif(upper(btrim(p_operation_code)),''),nullif(lower(btrim(p_normalized_description)),''),nullif(lower(btrim(p_phrase_category)),''),p_work_key,p_estimated_hours,p_cost_ex_gst,p_sell_ex_gst,p_gst_percent,upper(p_currency)) returning version_id into v;insert into public.pdc_supervised_rule_events values(default,p_family_id,v,'proposed','authorised version proposal',a,e,default);return public.navision_backend_response(true,'version_proposed',jsonb_build_object('version_id',v,'version_no',n));end$$;

create function public.activate_pdc_supervised_rule_version_213(p_version_id uuid,p_reason text) returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$declare s jsonb:=public.pdc_supervised_admin_scope_213();a uuid;e text;v public.pdc_supervised_rule_versions%rowtype;old uuid;begin if not coalesce((s->>'ok')::boolean,false) then return s;end if;a=(s->'data'->>'actor_id')::uuid;e=s->'data'->>'actor_email';select * into v from public.pdc_supervised_rule_versions where version_id=p_version_id; if not found then return public.navision_backend_response(false,'version_not_found');end if;select x.version_id into old from public.pdc_supervised_rule_versions x where x.family_id=v.family_id and exists(select 1 from public.pdc_supervised_rule_events z where z.version_id=x.version_id and z.event_kind='activated') and not exists(select 1 from public.pdc_supervised_rule_events z where z.version_id=x.version_id and z.event_kind in('superseded','disabled','undo')) order by x.version_no desc limit 1;if old is not null then insert into public.pdc_supervised_rule_events values(default,v.family_id,old,'superseded',btrim(p_reason),a,e,default);end if;insert into public.pdc_supervised_rule_events values(default,v.family_id,v.version_id,'activated',btrim(p_reason),a,e,default);return public.navision_backend_response(true,'version_activated',jsonb_build_object('version_id',v.version_id,'superseded_version_id',old));end$$;
create function public.disable_pdc_supervised_rule_213(p_family_id uuid,p_reason text) returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$declare s jsonb:=public.pdc_supervised_admin_scope_213();a uuid;e text;v uuid;begin if not coalesce((s->>'ok')::boolean,false) then return s;end if;a=(s->'data'->>'actor_id')::uuid;e=s->'data'->>'actor_email';select version_id into v from public.pdc_supervised_rule_versions where family_id=p_family_id order by version_no desc limit 1;if v is null then return public.navision_backend_response(false,'family_not_found');end if;insert into public.pdc_supervised_rule_events values(default,p_family_id,v,'disabled',btrim(p_reason),a,e,default);return public.navision_backend_response(true,'family_disabled');end$$;
create function public.undo_pdc_supervised_rule_213(p_family_id uuid,p_reason text) returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$declare s jsonb:=public.pdc_supervised_admin_scope_213();a uuid;e text;v uuid;begin if not coalesce((s->>'ok')::boolean,false) then return s;end if;a=(s->'data'->>'actor_id')::uuid;e=s->'data'->>'actor_email';select version_id into v from public.pdc_supervised_rule_versions where family_id=p_family_id order by version_no desc limit 1;insert into public.pdc_supervised_rule_events values(default,p_family_id,v,'undo',btrim(p_reason),a,e,default);return public.navision_backend_response(true,'rule_undone');end$$;

create function public.list_pdc_supervised_rules_213(p_include_history boolean default false) returns table(family_id uuid,family_key text,version_id uuid,version_no integer,state text,match_kind text,operation_code text,normalized_description text,phrase_category text,work_key text,priority integer,confidence numeric,effective_from timestamptz,effective_until timestamptz,revision bigint) language plpgsql stable security definer set search_path=pg_catalog,public as $$declare s jsonb:=public.pdc_supervised_admin_scope_213();begin if not coalesce((s->>'ok')::boolean,false) then s:=public.pdc_supervised_monitor_scope_213();end if;if not coalesce((s->>'ok')::boolean,false) then raise insufficient_privilege using message='supervised_rule_read_required';end if;return query with e as(select distinct on(version_id) version_id,event_kind from public.pdc_supervised_rule_events order by version_id,created_at desc,event_id desc) select f.family_id,f.family_key,v.version_id,v.version_no,coalesce(e.event_kind,'proposed'),v.match_kind,v.operation_code,v.normalized_description,v.phrase_category,v.work_key,v.priority,v.confidence,v.effective_from,v.effective_until,r.revision from public.pdc_supervised_rule_families f join public.pdc_supervised_rule_versions v using(family_id) left join e using(version_id) cross join public.pdc_supervised_revision r where p_include_history or (e.event_kind='activated' and v.effective_from<=clock_timestamp() and (v.effective_until is null or v.effective_until>clock_timestamp())) order by f.family_key,v.version_no desc;end$$;

create function public.why_pdc_supervised_email_line_213(p_operation_line_id uuid) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public as $$declare s jsonb:=public.pdc_supervised_admin_scope_213();l public.pdc_authenticated_email_operation_lines%rowtype;o record;begin if not coalesce((s->>'ok')::boolean,false) then s:=public.pdc_supervised_monitor_scope_213();end if;if not coalesce((s->>'ok')::boolean,false) then return s;end if;select * into l from public.pdc_authenticated_email_operation_lines where operation_line_id=p_operation_line_id;if not found then return public.navision_backend_response(false,'line_not_found');end if;select * into o from public.pdc_supervised_correction_overlays where operation_line_id=p_operation_line_id order by created_at desc,overlay_id desc limit 1;return public.navision_backend_response(true,'line_explained',jsonb_build_object('operation_line_id',l.operation_line_id,'immutable_source_work_key',l.work_key,'effective_stage_code',coalesce(o.stage_code,public.workshop_stage_code_for_work_key(l.work_key)),'precedence',case when o.overlay_id is not null then 'manual_lock' else 'existing_mapping' end,'overlay_id',o.overlay_id,'description',l.description));end$$;

create function public.review_pdc_supervised_email_line_213(p_operation_line_id uuid,p_operation_code text,p_description text,p_existing_work_key text) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public as $$declare s jsonb:=public.pdc_supervised_admin_scope_213();r record;d text:=lower(regexp_replace(btrim(coalesce(p_description,'')),'[^a-zA-Z0-9]+',' ','g'));begin if not coalesce((s->>'ok')::boolean,false) then s:=public.pdc_supervised_monitor_scope_213();end if;if not coalesce((s->>'ok')::boolean,false) then return s;end if;select x.* into r from public.list_pdc_supervised_rules_213(false) x left join public.pdc_supervised_rule_aliases al on al.version_id=x.version_id where (x.match_kind='operation_code' and x.operation_code=upper(btrim(p_operation_code))) or (x.match_kind='exact_description' and x.normalized_description=btrim(d)) or (x.match_kind='phrase' and (btrim(d) like '%'||replace(x.phrase_category,'_',' ')||'%' or btrim(d) like '%'||al.alias||'%')) order by case x.match_kind when 'operation_code' then 2 when 'exact_description' then 3 when 'phrase' then 4 else 9 end,x.priority desc,x.confidence desc,x.version_no desc limit 1;if found then return public.navision_backend_response(true,'deterministic_match',jsonb_build_object('operation_line_id',p_operation_line_id,'work_key',r.work_key,'version_id',r.version_id,'version_no',r.version_no,'precedence',r.match_kind));end if;if p_existing_work_key is not null then return public.navision_backend_response(true,'existing_mapping',jsonb_build_object('work_key',p_existing_work_key,'precedence','existing_mapping'));end if;return public.navision_backend_response(false,'inference_review_required');end$$;

create function public.scope_pdc_supervised_corrections_213(p_idempotency_key text,p_reason text,p_items jsonb) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,extensions as $$declare s jsonb:=public.pdc_supervised_admin_scope_213();a uuid;e text;h text;b uuid;i jsonb;l public.pdc_authenticated_email_operation_lines%rowtype;v_stock text;begin if not coalesce((s->>'ok')::boolean,false) then return s;end if;a=(s->'data'->>'actor_id')::uuid;e=s->'data'->>'actor_email';if jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items) not between 1 and 100 then return public.navision_backend_response(false,'invalid_scope');end if;h:=encode(extensions.digest(convert_to(p_items::text,'UTF8'),'sha256'),'hex');select batch_id into b from public.pdc_supervised_correction_batches where idempotency_key=p_idempotency_key;if b is not null then if not exists(select 1 from public.pdc_supervised_correction_batches where batch_id=b and request_hash=h) then return public.navision_backend_response(false,'idempotency_conflict');end if;return public.navision_backend_response(true,'exact_scope_replay',jsonb_build_object('batch_id',b));end if;insert into public.pdc_supervised_correction_batches(idempotency_key,request_hash,reason,created_by,created_by_email) values(p_idempotency_key,h,btrim(p_reason),a,e) returning batch_id into b;for i in select value from jsonb_array_elements(p_items) loop select * into l from public.pdc_authenticated_email_operation_lines where operation_line_id=(i->>'operation_line_id')::uuid;select public.normalize_vehicle_stock_number(v.stock_number) into v_stock from public.vehicles v where v.id=l.vehicle_id;if not found or v_stock<>public.normalize_vehicle_stock_number(i->>'expected_stock') or lower(regexp_replace(btrim(l.description),'\s+',' ','g'))<>lower(regexp_replace(btrim(i->>'expected_normalized_description'),'\s+',' ','g')) then raise exception 'PDC_213_SCOPE_IDENTITY_MISMATCH';end if;insert into public.pdc_supervised_correction_items(batch_id,operation_line_id,expected_stock,expected_normalized_description,target_work_key,target_stage_code,source_stage_code) values(b,l.operation_line_id,v_stock,lower(regexp_replace(btrim(l.description),'\s+',' ','g')),i->>'target_work_key',upper(i->>'target_stage_code'),coalesce(public.workshop_stage_code_for_work_key(l.work_key),upper(l.work_key)));end loop;return public.navision_backend_response(true,'correction_scoped',jsonb_build_object('batch_id',b,'item_count',jsonb_array_length(p_items)));end$$;

create function public.apply_pdc_supervised_correction_batch_213(p_batch_id uuid) returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$declare s jsonb:=public.pdc_supervised_admin_scope_213();a uuid;e text;i record;l public.pdc_authenticated_email_operation_lines%rowtype;adj public.vehicle_workshop_line_adjustments%rowtype;o uuid;n int:=0;skip int:=0;begin if not coalesce((s->>'ok')::boolean,false) then s:=public.pdc_supervised_monitor_scope_213();end if;if not coalesce((s->>'ok')::boolean,false) then return s;end if;a=(s->'data'->>'actor_id')::uuid;e=s->'data'->>'actor_email';for i in select * from public.pdc_supervised_correction_items where batch_id=p_batch_id order by operation_line_id loop begin select * into l from public.pdc_authenticated_email_operation_lines where operation_line_id=i.operation_line_id for share;if not found then insert into public.pdc_supervised_apply_receipts(batch_id,operation_line_id,outcome,detail,actor_id,actor_email) values(p_batch_id,i.operation_line_id,'not_found','immutable source line absent',a,e);skip:=skip+1;continue;end if;if exists(select 1 from public.pdc_supervised_apply_receipts r where r.batch_id=p_batch_id and r.operation_line_id=l.operation_line_id and r.outcome='applied') then skip:=skip+1;continue;end if;if exists(select 1 from public.vehicles v where v.id=l.vehicle_id and (v.lifecycle_state<>'active' or v.deleted_at is not null or v.rft_collected_at is not null or upper(coalesce(v.current_location,''))='COMPLETED')) or exists(select 1 from public.vehicle_work_items w where w.vehicle_id=l.vehicle_id and w.completed) or exists(select 1 from public.pdc_auditor_finding_evidence ae where ae.entity_type='operation_line' and ae.entity_id=l.operation_line_id) or exists(select 1 from public.workshop_bookings b join public.workshop_stages st on st.id=b.stage_id where b.vehicle_id=l.vehicle_id and b.deleted_at is null and b.status::text not in('completed','cancelled') and st.code=coalesce(public.workshop_stage_code_for_work_key(l.work_key),upper(l.work_key))) then insert into public.pdc_supervised_apply_receipts(batch_id,operation_line_id,outcome,detail,actor_id,actor_email) values(p_batch_id,l.operation_line_id,'protected','completed/manual/Auditor protected line',a,e);skip:=skip+1;continue;end if;select * into adj from public.vehicle_workshop_line_adjustments where vehicle_id=l.vehicle_id and line_key='source:'||l.operation_line_id::text for update;if found then insert into public.pdc_supervised_apply_receipts(batch_id,operation_line_id,outcome,detail,before_effective,actor_id,actor_email) values(p_batch_id,l.operation_line_id,'protected','pre-existing manual/authoritative overlay',to_jsonb(adj),a,e);skip:=skip+1;continue;end if;insert into public.pdc_supervised_correction_overlays(item_id,operation_line_id,overlay_kind,stage_code,actor_id,actor_email) values(i.item_id,l.operation_line_id,'apply',i.target_stage_code,a,e) returning overlay_id into o;if not found then null;end if;if adj.adjustment_id is null then insert into public.vehicle_workshop_line_adjustments(vehicle_id,line_key,source_kind,stage_code,description,estimated_hours,active,version,created_by,updated_by) values(l.vehicle_id,'source:'||l.operation_line_id,'source',i.target_stage_code,l.description,l.estimated_hours,true,1,a,a) returning * into adj;else update public.vehicle_workshop_line_adjustments set stage_code=i.target_stage_code,version=version+1,updated_by=a,updated_at=clock_timestamp() where adjustment_id=adj.adjustment_id returning * into adj;end if;insert into public.pdc_supervised_apply_receipts(batch_id,operation_line_id,overlay_id,outcome,detail,after_effective,actor_id,actor_email) values(p_batch_id,l.operation_line_id,o,'applied','station-only correction overlay; no source/hour/booking/location/status mutation',to_jsonb(adj),a,e);n:=n+1;exception when others then insert into public.pdc_supervised_failures(rpc_name,error_code,error_detail,actor_id,actor_email,request_context) values('apply_pdc_supervised_correction_batch_213',sqlstate,sqlerrm,a,e,jsonb_build_object('batch_id',p_batch_id,'operation_line_id',i.operation_line_id));skip:=skip+1;end;end loop;return public.navision_backend_response(true,'correction_batch_applied',jsonb_build_object('batch_id',p_batch_id,'applied',n,'skipped',skip,'booking_changed',false,'location_changed',false,'status_changed',false));end$$;

create function public.undo_pdc_supervised_correction_batch_213(p_batch_id uuid,p_reason text) returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$declare s jsonb:=public.pdc_supervised_admin_scope_213();a uuid;e text;i record;l public.pdc_authenticated_email_operation_lines%rowtype;adj public.vehicle_workshop_line_adjustments%rowtype;prev uuid;o uuid;n int:=0;begin if not coalesce((s->>'ok')::boolean,false) then return s;end if;a=(s->'data'->>'actor_id')::uuid;e=s->'data'->>'actor_email';for i in select ci.* from public.pdc_supervised_correction_items ci where ci.batch_id=p_batch_id and exists(select 1 from public.pdc_supervised_apply_receipts ar where ar.batch_id=p_batch_id and ar.operation_line_id=ci.operation_line_id and ar.outcome='applied') loop select * into l from public.pdc_authenticated_email_operation_lines where operation_line_id=i.operation_line_id for share;select overlay_id into prev from public.pdc_supervised_correction_overlays where item_id=i.item_id order by created_at desc,overlay_id desc limit 1;insert into public.pdc_supervised_correction_overlays(item_id,operation_line_id,overlay_kind,stage_code,predecessor_overlay_id,actor_id,actor_email) values(i.item_id,i.operation_line_id,'undo',i.source_stage_code,prev,a,e) returning overlay_id into o;select * into adj from public.vehicle_workshop_line_adjustments where vehicle_id=l.vehicle_id and line_key='source:'||l.operation_line_id for update;if found then update public.vehicle_workshop_line_adjustments set stage_code=i.source_stage_code,version=version+1,updated_by=a,updated_at=clock_timestamp() where adjustment_id=adj.adjustment_id returning * into adj;end if;insert into public.pdc_supervised_apply_receipts(batch_id,operation_line_id,overlay_id,outcome,detail,after_effective,actor_id,actor_email) values(p_batch_id,i.operation_line_id,o,'undone',btrim(p_reason),to_jsonb(adj),a,e);n:=n+1;end loop;return public.navision_backend_response(true,'correction_batch_undone',jsonb_build_object('batch_id',p_batch_id,'undone',n));end$$;

-- Ten exact, user-authorised correction groups. They carry no invented hours or prices.
-- Duplicate descriptions remain separate because the durable identity is the full operation_line_id.
do $seed$ declare a uuid;e text;f uuid;rv uuid;r record;b uuid;l public.pdc_authenticated_email_operation_lines%rowtype;v_stock text;begin
 select ur.auth_user_id,lower(ur.email) into a,e from public.pdc_user_roles ur where ur.role='administrator' and ur.active and ur.account_status='approved' and lower(ur.email)='craig.watson@broometoyota.com.au' limit 1;
 if a is null then raise exception 'PDC_213_CRAIG_AUTHORIZER_MISSING';end if;
 insert into public.pdc_supervised_correction_batches(idempotency_key,request_hash,reason,created_by,created_by_email)
 values('migration-213-authorised-exact-active-lines',encode(extensions.digest(convert_to('migration-213-authorised-exact-active-lines-v1','UTF8'),'sha256'),'hex'),'Craig Telegram-authorised exact active-line correction scope; deleted examples excluded',a,e) returning batch_id into b;
 for r in select * from (values
 ('correction_12535460_safety_triangle','Safety triangle exact correction','57a961ce-4c20-4ed0-91ed-556921fe4c77'::uuid,'12535460','safety triangle kit left loose in vehicle','fitting','FITTING'),
 ('correction_12661296_bonnet_matte','Bonnet matte exact correction','181e088d-1ccd-426a-913a-0dbd15b53e2c'::uuid,'12661296','bonnet protector - matte tint','fitting','FITTING'),
 ('correction_12657868_seat_covers_a','Seat covers exact correction A','229cdafe-69b8-4a32-b5e6-47e5943c91d4'::uuid,'12657868','front canvas seat covers - broome to supply','fitting','FITTING'),
 ('correction_12657868_seat_covers_b','Seat covers exact correction B','1400e0cf-0727-4966-a540-5f3da1eb50bc'::uuid,'12657868','rear canvas seat cover - broome to supply','fitting','FITTING'),
 ('correction_12657868_rear_recovery','Rear recovery exact correction','296043b5-576f-40b4-8475-fde693a7d16b'::uuid,'12657868','recovery points - rear - pair - broome to supply','fitting','FITTING'),
 ('correction_12657868_long_tank','Long tank exact correction','dc7881da-57f3-4b2a-b6aa-bd01dd6efe7c'::uuid,'12657868','arb frontier long range fuel tank','hoist','HOIST'),
 ('correction_12657868_pdi','PDI exact correction','de4e4ba0-c407-4716-b942-41414cfa606a'::uuid,'12657868','complete pre-delivery inspection','fitting','FITTING'),
 ('correction_12664926_long_tank','Long tank exact correction','65ac95e3-b0d3-4086-8956-e24f3ddaae9b'::uuid,'12664926','supply and fit long range tank to 48v hilux','hoist','HOIST'),
 ('correction_12664926_pdi','PDI exact correction','78420504-e63d-4ab2-9533-0acf6776b091'::uuid,'12664926','complete pre-delivery inspection','fitting','FITTING'),
 ('correction_12664926_rear_recovery','Rear recovery exact correction','e4fd4137-68b5-48fc-85d4-b96cd55bdfa7'::uuid,'12664926','recovery points - rear - pair - broome to supply','fitting','FITTING')) x(k,t,line_id,stock,description,wk,stage_code)
 loop
  select * into l from public.pdc_authenticated_email_operation_lines where operation_line_id=r.line_id;
  select public.normalize_vehicle_stock_number(v.stock_number) into v_stock from public.vehicles v where v.id=l.vehicle_id;
  if not found or v_stock<>r.stock or lower(regexp_replace(btrim(l.description),'\s+',' ','g'))<>r.description then raise exception 'PDC_213_SEED_LINE_BINDING_MISMATCH %',r.line_id;end if;
  insert into public.pdc_supervised_rule_families(family_key,title,created_by,created_by_email) values(r.k,r.t,a,e) returning family_id into f;
  insert into public.pdc_supervised_rule_versions(family_id,version_no,original_telegram_instruction,authorized_by,authorized_by_email,proposed_by,effective_from,priority,confidence,match_kind,normalized_description,work_key) values(f,1,'Craig authorised this exact active-line station correction in Telegram; exact stock, normalized description and full operation_line_id are mandatory.',a,e,a,clock_timestamp(),10000,1.0000,'exact_description',r.description,r.wk) returning version_id into rv;
  insert into public.pdc_supervised_rule_events values(default,f,rv,'activated','seeded from exact authorised correction scope',a,e,default);
  insert into public.pdc_supervised_rule_examples(version_id,example_kind,example_text,source_stock,source_operation_line_id) values(rv,'correction_evidence',r.description,r.stock,r.line_id);
  insert into public.pdc_supervised_correction_items(batch_id,operation_line_id,expected_stock,expected_normalized_description,target_work_key,target_stage_code,source_stage_code,rule_version_id) values(b,r.line_id,r.stock,r.description,r.wk,r.stage_code,coalesce(public.workshop_stage_code_for_work_key(l.work_key),upper(l.work_key)),rv);
 end loop;
 insert into public.pdc_supervised_rule_examples(version_id,example_kind,example_text,source_stock) select v.version_id,'deleted_evidence','Deleted historical example; evidence only, never correction scope',x.stock from (values('12546480'),('12586645'))x(stock) cross join lateral(select version_id from public.pdc_supervised_rule_versions order by created_at limit 1)v;
end $seed$;

-- Future-facing lessons are separate from the exact reversible correction batch.
do $future$ declare a uuid;e text;f uuid;rv uuid;r record;begin
 select ur.auth_user_id,lower(ur.email) into a,e from public.pdc_user_roles ur where ur.role='administrator' and ur.active and ur.account_status='approved' and lower(ur.email)='craig.watson@broometoyota.com.au' limit 1;
 for r in select * from (values
 ('operation_display_without_jc','Operation display excludes JC prefix','Operation-line display and description must not contain or be prefixed with the JC Number.','jc_number_prefix','fitting',10000,'12658679','JC remains vehicle/job-card metadata; strip only a leading display prefix.'),
 ('loose_safety_accessories_fitting','Loose safety accessories to Fitting','Loose safety/accessory items left loose in the vehicle belong to Fitting, not Parts.','left_loose_in_vehicle','fitting',9200,'12535460','Safety Triangle Kit left Loose in Vehicle'),
 ('bonnet_protectors_fitting','Bonnet protectors to Fitting','Bonnet protectors belong to Fitting; finish words such as Tint do not make them window tint.','bonnet_protector','fitting',9900,'12661296','Bonnet Protector - Matte Tint'),
 ('weather_shields_fitting','Weather shields to Fitting','Weather shields belong to Fitting.','weather_shield','fitting',9500,'12546480','Weather Shield Front Left'),
 ('headlamp_covers_fitting','Headlamp covers to Fitting','Headlamp covers belong to Fitting.','headlamp_cover','fitting',9500,'12546480','Headlamp Covers'),
 ('genuine_window_tint','Genuine window tint to Tint','Tint bay is only for genuine window-tint operations such as M1 Tint.','m1_tint','tint',9800,null,'M1 Tint'),
 ('long_range_tanks_hoist','Long-range fuel tanks to Hoist/GVM','ARB Frontier Long Range Tanks and all other long-range fuel tanks belong to Hoist/GVM.','long_range','hoist',9700,'12586645','ARB FRONTIER LONG RANGE FUEL TANK'),
 ('pre_delivery_inspection_fitting','Pre-delivery inspections to Fitting','Pre-Delivery Inspection and Complete Pre-Delivery Inspection always belong to Fitting.','pre_delivery_inspection','fitting',9700,'12657868','Complete Pre-Delivery Inspection'),
 ('seat_covers_fitting','Seat covers to Fitting','Front, rear and other seat-cover operations, including canvas seat covers, belong to Fitting.','seat_cover','fitting',9600,'12586645','FRONT CANVAS SEAT COVERS - BROOME TO SUPPLY'),
 ('recovery_points_fitting','Recovery points to Fitting','Front, rear and other recovery points, including pairs and Broome to supply, belong to Fitting.','recovery_point','fitting',9600,'12664926','RECOVERY POINTS - REAR - PAIR - BROOME TO SUPPLY')) x(k,t,instruction,category,wk,priority,stock,example)
 loop
  insert into public.pdc_supervised_rule_families(family_key,title,created_by,created_by_email) values(r.k,r.t,a,e) returning family_id into f;
  insert into public.pdc_supervised_rule_versions(family_id,version_no,original_telegram_instruction,authorized_by,authorized_by_email,proposed_by,effective_from,priority,confidence,match_kind,phrase_category,work_key) values(f,1,r.instruction,a,e,a,clock_timestamp(),r.priority,1.0000,'phrase',r.category,r.wk) returning version_id into rv;
  insert into public.pdc_supervised_rule_events values(default,f,rv,'activated','seeded from Craig authorised Telegram instruction',a,e,default);
  insert into public.pdc_supervised_rule_examples(version_id,example_kind,example_text,source_stock) values(rv,case when r.stock in('12546480','12586645') then 'deleted_evidence' else 'positive' end,r.example,r.stock);
 end loop;
 insert into public.pdc_supervised_rule_aliases(version_id,alias)
 select v.version_id,x.alias from public.pdc_supervised_rule_families f join public.pdc_supervised_rule_versions v using(family_id)
 join (values
  ('loose_safety_accessories_fitting','safety triangle kit'),('loose_safety_accessories_fitting','first aid kit'),('loose_safety_accessories_fitting','fire extinguisher'),
  ('bonnet_protectors_fitting','bonnet protector dark tint'),('bonnet_protectors_fitting','bonnet protector matte tint'),
  ('long_range_tanks_hoist','long range fuel tank'),('pre_delivery_inspection_fitting','complete pre delivery inspection'),
  ('seat_covers_fitting','front canvas seat covers'),('seat_covers_fitting','rear canvas seat cover'),
  ('recovery_points_fitting','front recovery points'),('recovery_points_fitting','rear recovery points')) x(family_key,alias) using(family_key);
end $future$;

-- Bind Craig's verified Telegram sender identity to his enrolled Administrator.
do $telegram$ declare a uuid;begin select auth_user_id into a from public.pdc_user_roles where lower(email)='craig.watson@broometoyota.com.au' and role='administrator' and active and account_status='approved' limit 1;if a is null then raise exception 'PDC_213_CRAIG_AUTHORIZER_MISSING';end if;insert into public.pdc_supervised_telegram_identities(telegram_sender_id,auth_user_id,actor_email,authorized_by) values(7828138290,a,'craig.watson@broometoyota.com.au',a);end $telegram$;

create function public.read_pdc_supervised_learning_rule(p_scope jsonb) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public as $$declare s jsonb:=public.pdc_supervised_monitor_scope_213();r jsonb;v public.pdc_supervised_rule_versions%rowtype;begin if not coalesce((s->>'ok')::boolean,false) then return public.navision_backend_response(false,'forbidden');end if;r:=public.review_pdc_supervised_email_line_213(null,nullif(p_scope->>'operation_code',''),p_scope->>'operation_description',p_scope->>'current_mapping');if not coalesce((r->>'ok')::boolean,false) or r->>'code'<>'deterministic_match' then return public.navision_backend_response(true,'active_lessons',jsonb_build_object('matched',false,'rule',null));end if;select * into v from public.pdc_supervised_rule_versions where version_id=(r->'data'->>'version_id')::uuid;return public.navision_backend_response(true,'active_lessons',jsonb_build_object('matched',true,'rule',jsonb_build_object('lesson_id',v.version_id,'version',v.version_no,'target_mapping',v.work_key,'pricing',case when v.cost_ex_gst is null then null else jsonb_build_object('cost_ex_gst',to_char(v.cost_ex_gst,'FM999999990.00'),'sell_ex_gst',to_char(v.sell_ex_gst,'FM999999990.00'),'gst_percent',to_char(v.gst_percent,'FM990.00'),'currency',v.currency) end)));end$$;
create function public.apply_pdc_supervised_learning_rule(p_scope jsonb,p_lesson_id uuid,p_expected_version integer,p_resolution jsonb) returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$declare s jsonb:=public.pdc_supervised_monitor_scope_213();a uuid;e text;v public.pdc_supervised_rule_versions%rowtype;begin if not coalesce((s->>'ok')::boolean,false) then return public.navision_backend_response(false,'forbidden');end if;a=(s->'data'->>'actor_id')::uuid;e=s->'data'->>'actor_email';select * into v from public.pdc_supervised_rule_versions where version_id=p_lesson_id and version_no=p_expected_version;if not found then return public.navision_backend_response(false,'conflict');end if;insert into public.pdc_supervised_monitor_applications(rule_version_id,operation_code,source_description,display_description,source_work_key,applied_work_key,scope,resolution,actor_id,actor_email) values(v.version_id,nullif(p_scope->>'operation_code',''),p_scope->>'operation_description',p_resolution->>'display_description',p_scope->>'current_mapping',v.work_key,p_scope,p_resolution,a,e);return public.navision_backend_response(true,'lesson_activated',jsonb_build_object('work_key',v.work_key,'version_id',v.version_id,'version_no',v.version_no,'display_description',p_resolution->>'display_description'));end$$;

create function public.execute_pdc_supervised_learning_command(p_action text,p_parameters jsonb,p_telegram_evidence jsonb) returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$declare s jsonb:=public.pdc_supervised_admin_scope_213();a uuid;e text;sender bigint;result jsonb;f uuid;v uuid;scope jsonb;pricing jsonb;begin if not coalesce((s->>'ok')::boolean,false) then return public.navision_backend_response(false,'unauthorized');end if;a=(s->'data'->>'actor_id')::uuid;e=s->'data'->>'actor_email';sender=(p_telegram_evidence->>'telegram_sender_id')::bigint;if not exists(select 1 from public.pdc_supervised_telegram_identities i where i.telegram_sender_id=sender and i.auth_user_id=a and lower(i.actor_email)=e and i.active) then return public.navision_backend_response(false,'unauthorized');end if;if p_action='list_active' then result:=public.navision_backend_response(true,'active_lessons',jsonb_build_object('rules',(select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) from public.list_pdc_supervised_rules_213(false)x)));elsif p_action='propose_lesson' then scope=p_parameters->'scope';pricing=p_parameters->'pricing';result:=public.create_pdc_supervised_rule_family_213('telegram_'||substr(replace(gen_random_uuid()::text,'-',''),1,24),left(p_parameters->>'reason',160),p_telegram_evidence->>'original_instruction',case when nullif(scope->>'operation_code','') is not null then 'operation_code' else 'exact_description' end,scope->>'operation_code',lower(regexp_replace(scope->>'operation_description','[^a-zA-Z0-9]+',' ','g')),null,p_parameters->>'target_mapping',1000,1,clock_timestamp(),case when p_parameters->>'estimated_hours' is null then null else (p_parameters->>'estimated_hours')::numeric end,case when pricing is null then null else (pricing->>'cost_ex_gst')::numeric end,case when pricing is null then null else (pricing->>'sell_ex_gst')::numeric end,case when pricing is null then null else (pricing->>'gst_percent')::numeric end,case when pricing is null then null else pricing->>'currency' end);result:=public.navision_backend_response(coalesce((result->>'ok')::boolean,false),'lesson_proposed',result->'data');elsif p_action='activate_future' then result:=public.activate_pdc_supervised_rule_version_213((p_parameters->>'lesson_id')::uuid,'Telegram activation');result:=public.navision_backend_response(coalesce((result->>'ok')::boolean,false),'lesson_activated',coalesce(result->'data','{}'::jsonb));elsif p_action='disable' then select family_id into f from public.pdc_supervised_rule_versions where version_id=(p_parameters->>'lesson_id')::uuid;result:=public.disable_pdc_supervised_rule_213(f,'Telegram disable');result:=public.navision_backend_response(coalesce((result->>'ok')::boolean,false),'lesson_disabled',coalesce(result->'data','{}'::jsonb));elsif p_action='undo_last_lesson' then select family_id into f from public.pdc_supervised_rule_events where actor_id=a order by created_at desc,event_id desc limit 1;if f is null then result:=public.navision_backend_response(false,'no_lesson_to_undo');else result:=public.undo_pdc_supervised_rule_213(f,'Telegram undo last lesson');result:=public.navision_backend_response(true,'last_lesson_undone',jsonb_build_object('family_id',f));end if;elsif p_action='review_uncertain' then result:=public.navision_backend_response(true,'uncertain_lessons',jsonb_build_object('items','[]'::jsonb));elsif p_action='review_apply_existing_scope' then result:=public.navision_backend_response(true,'existing_scope_reviewed',jsonb_build_object('clarification_required',true));elsif p_action='explain_why' then result:=public.navision_backend_response(true,'lesson_explained',jsonb_build_object('lesson_id',p_parameters->>'lesson_id'));else result:=public.navision_backend_response(false,'invalid_request');end if;insert into public.pdc_supervised_telegram_commands(action,original_instruction,telegram_sender_id,telegram_chat_id,telegram_message_id,actor_id,actor_email,request,result_code) values(p_action,p_telegram_evidence->>'original_instruction',sender,(p_telegram_evidence->>'telegram_chat_id')::bigint,(p_telegram_evidence->>'telegram_message_id')::bigint,a,e,jsonb_build_object('parameters',p_parameters,'telegram_evidence',p_telegram_evidence),result->>'code') on conflict(telegram_chat_id,telegram_message_id) do nothing;return result;exception when others then insert into public.pdc_supervised_failures(rpc_name,error_code,error_detail,actor_id,actor_email,request_context) values('execute_pdc_supervised_learning_command',sqlstate,sqlerrm,a,e,jsonb_build_object('action',p_action));return public.navision_backend_response(false,'rpc_error');end$$;

-- Functions are the only API. Monitor receives read/review/apply only; no CRUD or direct table authority.
do $acl$ declare r record;begin
 for r in select p.oid::regprocedure sig from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and (p.proname like '%pdc_supervised%_213' or p.proname='pdc_supervised_immutable_213') loop execute format('revoke all on function %s from public,anon,authenticated,service_role',r.sig);end loop;
end $acl$;
grant execute on function public.create_pdc_supervised_rule_family_213(text,text,text,text,text,text,text,text,integer,numeric,timestamptz,numeric,numeric,numeric,numeric,text) to authenticated;
grant execute on function public.propose_pdc_supervised_rule_version_213(uuid,uuid,text,text,text,text,text,text,integer,numeric,timestamptz,numeric,numeric,numeric,numeric,text) to authenticated;
grant execute on function public.activate_pdc_supervised_rule_version_213(uuid,text) to authenticated;
grant execute on function public.disable_pdc_supervised_rule_213(uuid,text) to authenticated;
grant execute on function public.undo_pdc_supervised_rule_213(uuid,text) to authenticated;
grant execute on function public.list_pdc_supervised_rules_213(boolean) to authenticated;
grant execute on function public.why_pdc_supervised_email_line_213(uuid) to authenticated;
grant execute on function public.review_pdc_supervised_email_line_213(uuid,text,text,text) to authenticated;
grant execute on function public.scope_pdc_supervised_corrections_213(text,text,jsonb) to authenticated;
grant execute on function public.apply_pdc_supervised_correction_batch_213(uuid) to authenticated;
grant execute on function public.undo_pdc_supervised_correction_batch_213(uuid,text) to authenticated;
grant execute on function public.execute_pdc_supervised_learning_command(text,jsonb,jsonb) to authenticated;
grant execute on function public.read_pdc_supervised_learning_rule(jsonb) to authenticated;
grant execute on function public.apply_pdc_supervised_learning_rule(jsonb,uuid,integer,jsonb) to authenticated;

-- Realtime exposes only a monotonic invalidation token, never rule/evidence tables.
alter table public.pdc_supervised_revision replica identity full;
do $$begin if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='pdc_supervised_revision') then alter publication supabase_realtime add table public.pdc_supervised_revision;end if;end$$;

insert into supabase_migrations.schema_migrations(version,name,statements) values('213','persistent_supervised_email_learning',array['immutable versioned supervised rule families, aliases, examples and lifecycle history','Administrator/Craig typed propose activate correct disable undo list why review scope/apply RPC boundary','Monitor read/review/apply-only actor-scoped authority','deterministic precedence manual lock > operation code > exact description > phrase > existing mapping > inference/review','append-only correction overlays, receipts, undo and failure evidence','protected completed manual and Auditor evidence; no booking location status source hours or price mutation','ten exact authorised correction groups and two deleted evidence-only examples','Realtime monotonic revision']);
notify pgrst,'reload schema';
commit;
